"""Include every stored 1850–1899 series; distinguish inventory from calculation approval."""
import collections,hashlib,json,math,pathlib
R=pathlib.Path(__file__).resolve().parent;O=R.parents[2]/'docs/historical-metrics';O.mkdir(parents=True,exist_ok=True)
from snapshot_inputs import ensure_snapshot_inputs
ensure_snapshot_inputs(R)
def read(n):return json.loads((R/n).read_text())
def digest(x):return hashlib.sha256(json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
ind,fin,iv,fv=map(read,['indicators.json','finance.json','values.json','finance_values.json']);sourcechecks=read('source-checks.json');live=read('live-comparison.json');fc=read('finance-copy-comparison.json')
assert not live['unresolved_15ai'] and not fc['unresolved']
comparisons=live['results']+fc['results'];verified={(x['family'],x['series_key']):x for x in comparisons if not x['changes'] and x['checked_cells']==x['matched']}
assert not any(x['changes'] for x in comparisons),'Numerical changes require explicit revision before approval'
lookup={x['url']:x for x in sourcechecks};rows=[];concepts=collections.defaultdict(list);copies=collections.defaultdict(list)
for family,series,values in [('indicator',ind,iv),('finance',fin,fv)]:
 bykey=collections.defaultdict(list)
 for v in values:bykey[v['series_key']].append(v)
 for s in series:
  key=s['series_key'];vv=bykey[key];hist=[v for v in vv if 1850<=v['year']<=1899];assert hist,key
  m=s.get('metadata') or {};source=lookup.get(s.get('source_url'));reconciled=(family,key) in verified
  held=bool(m.get('publication_hold')) or bool(m.get('source_verification')=='pending') or str(s.get('source_key','')).startswith(('hist_cost_living_csv','hist_macro_csv','hist_structure_csv'))
  def usable(v):
   if held or v.get('value') is None or not math.isfinite(float(v['value'])):return False
   if not 1850<=v['year']<=2025:return False
   if reconciled:return True
   return v.get('value_kind')=='observed' and v.get('validation_status') in ('source_verified','source_snapshot_checked','pdf_table_visually_checked','official_source_claim_checked') and (family=='finance' or v.get('is_published',False)) and str(v.get('source_url') or s.get('source_url') or '').startswith(('https://','http://'))
  eligible=[v for v in vv if usable(v)]
  state='verified_current_numeric_snapshot' if reconciled else 'existing_checked_descriptive_cells' if eligible else 'estimate_or_derivation_review' if any(v.get('value_kind')=='estimate' or v.get('validation_status')=='calculation_checked' for v in vv) and not held else 'provenance_or_publication_review'
  concept='series:'+family+':'+key
  if family=='indicator' and m.get('table')=='15ai':concept='15ai:'+str(m.get('transaction','')).split(' ')[0]+':'+str(m.get('industry','')).split(' ')[0]
  if family=='finance' and reconciled and verified[family,key].get('source')=='15ai':
   sel=verified[family,key]['selection'];industry=sel['toimiala_79_20180101'];industry={'SSS':'Yhteensä','BTE':'B-E'}.get(industry,industry);concept='15ai:'+sel['taloustoimi_1_20180101']+':'+industry
  # A concept may have several representations. None receives aggregate weight by inclusion.
  canonical_cells=[{k:v.get(k) for k in ('year','group_key','period','value','value_kind')} for v in vv]
  fingerprints=sorted(canonical_cells,key=lambda x:json.dumps(x,sort_keys=True));fingerprint=digest([s['unit'],fingerprints])
  row={'record_key':family+':'+key,'source_family':family,'series_key':key,'title':s['title'],'included_in_historical_catalog':True,'calculation_status':state,'concept_key':concept,'unit':s['unit'],'geography':s.get('geography'),'frequency':s.get('frequency','source_defined'),'historical_years':sorted({v['year'] for v in hist}),'historical_rows':len(hist),'all_stored_rows':len(vv),'extension_years':sorted({v['year'] for v in vv if 1900<=v['year']<=2025}),'eligible_years':sorted({v['year'] for v in eligible}),'eligible_cells':len(eligible),'eligible_1800s_cells':sum(1850<=v['year']<=1899 for v in eligible),'row_statuses':dict(collections.Counter(v.get('validation_status') for v in vv)),'source_key':s.get('source_key'),'source_url':s.get('source_url'),'resolved_source_url':('https://pxdata.stat.fi/PxWeb/api/v1/fi/StatFin/ntp/15ai.px' if reconciled and verified[family,key]['source']=='15ai' else s.get('source_url')),'refresh_check':source.get('binary_comparison') if source else 'no_direct_source_url','source_currently_numeric_compared':reconciled,'publication_or_provenance_hold':held,'value_digest':fingerprint,'composite_approved':False,'weight':None,'do_not_interpolate':True,'limitations':s.get('comparability_notes') or m.get('limitations') or m.get('comparability') or m.get('method') or 'Source definitions, groups, geography and periods must be retained; inventory inclusion is not causal identification.'}
  rows.append(row);concepts[concept].append(row['record_key']);copies[fingerprint].append(row['record_key'])
assert len(rows)==536 and sum(x['source_family']=='indicator' for x in rows)==142
summary={'registry_id':'historical_metrics_1850_1899_20261026_v1','checked_on':'2026-10-26','scope':'All series with actual database observations dated 1850–1899, with existing extensions through 2025. Inclusion in the catalog does not approve numerical aggregation.','series':len(rows),'indicator_series':len(ind),'finance_series':len(fin),'historical_indicator_rows':sum(x['historical_rows'] for x in rows if x['source_family']=='indicator'),'historical_finance_rows':sum(x['historical_rows'] for x in rows if x['source_family']=='finance'),'calculation_statuses':dict(collections.Counter(x['calculation_status'] for x in rows)),'concept_groups':len(concepts),'verified_current_series':len(verified),'verified_current_cells':sum(x['matched'] for x in comparisons),'numeric_changes_detected':sum(len(x['changes']) for x in comparisons),'source_urls_checked':len(sourcechecks),'reachable_urls':sum(x['reachable'] for x in sourcechecks),'unchanged_pdf_urls':sum(x.get('binary_comparison')=='matches_existing_pdf' for x in sourcechecks),'attachment_only_sources':[s['source_key'] for s in read('sources.json') if not s.get('source_url')],'unverified_origin_csv_series':sum(str(s['source_key']).startswith(('hist_cost_living_csv','hist_macro_csv','hist_structure_csv')) for s in fin),'old_main_registry':'main_metrics_20261026_v1','normalization':None,'weights':None,'policy':{'all_historical_series_included':True,'all_series_equal_weight':False,'new_document_adds_weight':False,'all_series_approved_for_composite':False,'source_availability_is_not_numeric_verification':True,'different_sources_not_automatically_chain_linked':True,'source_values_unchanged':True,'new_snapshot_required_on_source_value_change':True},'source_hashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(R.glob('*.json')) if p.name not in ('registry.json',)}}
registry={'summary':summary,'series':rows,'concepts':[{'concept_key':k,'representations':v,'summable':False} for k,v in sorted(concepts.items())],'exact_stored_copy_candidates':[{'digest':k,'record_keys':v,'automatic_merge':False} for k,v in copies.items() if len(v)>1]};registry['content_sha256']=digest(registry)
(O/'registry.json').write_text(json.dumps(registry,ensure_ascii=False,indent=2)+'\n');(O/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
lines=['# Kaikki 1800-luvun mittarisarjat ja lähdepäivitysten tarkistus','','## Mitä muutettiin?','','Aiempi 18 päämittarin valinta oli suppea esityskerros. Sen rinnalle on nyt muodostettu kattava historiallinen mittarirekisteri: kaikki 142 indikaattorisarjaa ja 394 julkisen talouden sarjaa, joilla on tietokannassa havaintoja vuosilta 1850–1899. Kaikki 536 sarjaa sisältyvät rekisteriin; yksittäisten sarjojen lähde- ja laskentakelpoisuutta ei oleteta samaksi. Nykyiset päämittarit ja aiemmat hyväksynnät säilyvät.','','## Tarkistuksen tulokset','',f"- Rekisterissä on {summary['historical_indicator_rows']} indikaattorihavaintoa ja {summary['historical_finance_rows']} julkisen talouden havaintoa vuosilta 1850–1899. Lähdeperheet voivat sisältää samaa tietoa.",f"- Kaikki {len(sourcechecks)} ilmoitettua verkkolähdettä ovat saatavilla. {summary['unchanged_pdf_urls']} PDF-osoitteen sisältötiiviste täsmää aiemmin tallennettuun. Saman dokumentin eri osoitteita ei pidä tulkita riippumattomiksi lähteiksi.",f"- StatFin 15ai-, 12am- ja 12aq-aineistoihin verrattiin {len(verified)} sarjaa ja {summary['verified_current_cells']} tallennettua solua. Luku kattaa myös sarjojen jo tallennetut myöhemmät vuodet. Numeerisia eroja löytyi {summary['numeric_changes_detected']}.",'- Tarkistus kattaa 15ai-sarjojen 38 varsinaista indikaattoriversiota ja niiden 38 julkisen talouden vastinetta sekä yhdeksän väestö-/kuolleisuussarjaa. Lähdeperheiden vastineet eivät ole 76 riippumatonta mittaria.',f"- Alkuperältään vielä varmistamattomista kolmesta CSV-aineistosta on {summary['unverified_origin_csv_series']} sarjaa. Ne sisältyvät rekisteriin, mutta eivät läpäise laskentakäyttöön hyväksymistä.",'- Kahdella Tilastokeskuksen liiteaineistolla ei ole lähderekisterissä suoraa URL-osoitetta. Uudemman 15ai-liitteen kaikki 38 sarjaa voitiin silti kohdistaa nykyiseen rajapintaan ja arvot täsmäsivät. Vanhaa 019-liitettä ei automaattisesti ketjuteta siihen.','','## Käyttöluokat','','| Luokka | Sarjoja |','|---|---:|']
for k,n in summary['calculation_statuses'].items():lines.append(f'| {k} | {n} |')
lines+=['','- verified_current_numeric_snapshot: kaikkien sarjan tallennettujen solujen numeerinen vastine tarkistettu nykyisestä StatFin-lähteestä. Hyväksyntä koskee kuvailevaa käyttöä ja säilytettyjä määritelmiä, ei syyvaikutusta.','- existing_checked_descriptive_cells: sarjassa on aiemmin lähdetarkistettuja julkaistuja havaintoja. Kelvolliset vuodet ja solumäärät on yksilöity; uusintatarkistus ei varmistanut kaikkia lukuja uudelleen.','- estimate_or_derivation_review: arvio tai johdettu luku tarvitsee oman laskentamenetelmän tarkistuksen. Historiallista tutkimusarviota ei muuteta mitatuksi havainnoksi.','- provenance_or_publication_review: lähdealkuperä, lähdeosoite, julkaisukelpoisuus tai tarkistustaso estää toistaiseksi laskentakäytön.','','## Yhteismitallisuus ja päällekkäisyys','','Kaikki sarjat eivät ole erillisiä yhteiskunnallisia tekijöitä. Esimerkiksi saman arvonlisäyksen markkamäärä, volyymi-indeksi ja toimialaosuus ovat saman ilmiön eri esityksiä. Alueet, sukupuolet, ikäryhmät, kokonaisuudet ja osat ovat omia ulottuvuuksiaan. registry.json sisältää eksplisiittiset 15ai-vastineiden konseptiryhmät. Muiden lähteiden ryhmittely säilyy varovaisena; täydellistä semanttista duplikaattiratkaisua ei väitetä.','','Rekisteriin lisääminen ei anna painoa. Yhteisindeksin painot ja normalisointi ovat määrittelemättä. Näin uuden dokumentin tai rinnakkaissarjan lisääminen ei itsessään nosta vuoden yhteiskuntapistettä.','','## Päivitysten tila','','Tässä tarkistuksessa ei löytynyt eroja uudelleen verrattuihin numeerisiin arvoihin eikä niihin tehty arvojen korvauksia. Verkkosivun saatavuus tai samana pysynyt PDF ei todista alkuperäisen tilaston virheettömyyttä. Rikostilastokoosteen sivuston ilmoittama versio on edelleen 1.2 (30.9.2025); StatFin 15ai:n näkyvä viimeisin päivitys on 18.9.2026 ja sarjapää 2025*.','','Julkaistujen lähteiden kaikki uudet mahdolliset vuosihavainnot eivät ole tämän tarkistuksen lupaus: StatFin-vertailu tarkisti olemassa olevat solut. Muiden lähteiden pidemmät uudet taulukot, muuttuneet määritelmät tai tuoreemmat tutkimusrekonstruktiot vaativat erillisen poiminnan. Tarkistus ei ole koko tutkimuskirjallisuuden kattava uusien aineistojen haku.','','## Seuraava käyttö','','Historiallisen tarkastelun tulee hakea tästä laajasta rekisteristä ajanjakson kannalta olennaiset mittarit, eikä rajautua 18 päämittariin. Päänäkymä voi säilyä pelkistettynä: tuotanto, väestö ja kuolleisuus, elinkeinorakenne sekä köyhäinhoito. Tarkennuksissa avataan toimialat, alueet, koulutus, asuminen, kontrolli ja muut saatavilla olevat ilmiöt.','','Puuttuvia välivuosia ei interpoloida automaattisesti. Elinajanodotteen monivuotiset jaksot, tutkimusten vuosikymmenpisteet ja vuositilastot erotetaan toisistaan. Nykyisiä tulonjakokäsitteitä tai työttömyysastetta ei siirretä 1800-luvulle. Historialliset markat ja kansantalouden tilinpidon sarjoissa käytetyt nykymarkat erotetaan; vuoden 1963 muunnosta ei tehdä kahdesti.','','## Toistettavuus','','Lähdepoiminnat ja kyselyt ovat scripts/data/historical-metrics-kansiossa. check-sources.py tarkistaa lähteiden saavutettavuuden ja PDF-tiivisteet; check-live-series.py ja check-finance-copies.py vertaavat numeeriset solut; build-registry.py muodostaa rekisterin jäädytetyistä aineistoista. Lähdearvoja ei muuteta. Koostetta voi päivittää uudella versionumerolla, kun lähdearvo tai menetelmä muuttuu.']
(O/'raportti.md').write_text('\n'.join(lines)+'\n');print(json.dumps(summary,ensure_ascii=False,indent=2))
